    new_value = vars["v2"]

    if old_value == 0:
        return None

    change = new_value - old_value
    change_ratio = change / old_value
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_value": old_value,
